/* EARTHUS V2 — GK2A official L2 CTH height bands + observed GMGSI appearance.
 * CTH remains the only source of cloud height. We rasterize source cells into
 * coarse altitude bands only to avoid connecting sparse valid cells with visible
 * triangle facets. Mask dilation/blur is display interpolation, not cloud synthesis.
 * No procedural cloud noise or vertical exaggeration is used.
 */
const BANDS=Object.freeze([
  Object.freeze({id:'0-3km',minM:0,maxM:3000}),
  Object.freeze({id:'3-6km',minM:3000,maxM:6000}),
  Object.freeze({id:'6-9km',minM:6000,maxM:9000}),
  Object.freeze({id:'9-12km',minM:9000,maxM:12000}),
  Object.freeze({id:'12-16km',minM:12000,maxM:16000}),
  Object.freeze({id:'16-25km',minM:16000,maxM:25001}),
]);
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const median=values=>{if(!values.length)return null;const a=[...values].sort((x,y)=>x-y),m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])*.5};
async function imageFromBlob(blob){const url=URL.createObjectURL(blob);try{const image=new Image();image.crossOrigin='anonymous';await new Promise((ok,no)=>{image.onload=ok;image.onerror=()=>no(new Error('GK2A_CTH_OBSERVED_IMAGE_DECODE'));image.src=url});return image}finally{URL.revokeObjectURL(url)}}
function observedCanvas(image,meta){const cv=document.createElement('canvas');cv.width=image.naturalWidth||image.width;cv.height=image.naturalHeight||image.height;const cx=cv.getContext('2d',{willReadFrequently:true});if(!cx)throw new Error('GK2A_CTH_CANVAS_CONTEXT');cx.drawImage(image,0,0);const px=cx.getImageData(0,0,cv.width,cv.height),d=px.data;if(meta.format==='la8')for(let i=0;i<d.length;i+=4){const l=Math.round(138+d[i]*117/255),a=Math.round(238*Math.pow(d[i+3]/255,.82));d[i]=d[i+1]=d[i+2]=l;d[i+3]=a}else for(let i=0;i<d.length;i+=4){const a=Math.round(238*Math.pow(d[i]/255,.82));d[i]=d[i+1]=d[i+2]=255;d[i+3]=a}cx.putImageData(px,0,0);return cv}
async function loadObserved(base){const mr=await fetch(`${base}/meta.json?t=${Date.now()}`,{cache:'no-cache'});if(!mr.ok)throw new Error(`GK2A_CTH_OBSERVED_META_${mr.status}`);const meta=await mr.json(),south=Number(meta?.south),north=Number(meta?.north);if(!meta?.time||!Number.isFinite(south)||!Number.isFinite(north)||north<=south)throw new Error('GK2A_CTH_OBSERVED_META_INVALID');const ir=await fetch(`${base}/global.png?t=${encodeURIComponent(meta.time)}`,{cache:'no-cache'});if(!ir.ok)throw new Error(`GK2A_CTH_OBSERVED_IMAGE_${ir.status}`);return Object.freeze({canvas:observedCanvas(await imageFromBlob(await ir.blob()),meta),meta:Object.freeze({time:meta.time,south,north,source:'NOAA_NESDIS_GMGSI',truthClass:'OBSERVED_2D_APPEARANCE'})})}
function pixelPoint(lon,lat,o,w,h){return{x:clamp((lon+180)/360)*(w-1),y:clamp((o.meta.north-lat)/Math.max(1e-6,o.meta.north-o.meta.south))*(h-1)}}
function estimateSourceStepPx(g,o,w,h){const span=Math.max(1e-6,o.meta.north-o.meta.south),steps=[];const stride=Math.max(1,Math.floor((g.width*g.height)/7000));for(let i=0;i<g.width*g.height;i+=stride){if(g.valid[i]!==1)continue;const x=i%g.width,y=Math.floor(i/g.width),lon=Number(g.longitude[i]),lat=Number(g.latitude[i]);if(x+1<g.width&&g.valid[i+1]===1){const v=Math.abs(Number(g.longitude[i+1])-lon)*w/360;if(Number.isFinite(v)&&v>.15&&v<80)steps.push(v)}if(y+1<g.height&&g.valid[i+g.width]===1){const v=Math.abs(Number(g.latitude[i+g.width])-lat)*h/span;if(Number.isFinite(v)&&v>.15&&v<80)steps.push(v)}if(steps.length>3000)break}return clamp(median(steps)||3,1.5,32)}
function buildBandTexture(g,o,band,sourceStep){const w=o.canvas.width,h=o.canvas.height,raw=document.createElement('canvas');raw.width=w;raw.height=h;const rc=raw.getContext('2d');if(!rc)throw new Error('GK2A_CTH_MASK_CONTEXT');rc.fillStyle='#fff';const heights=[],radius=clamp(sourceStep*.72,1.6,22);let cells=0;rc.beginPath();for(let i=0;i<g.width*g.height;i++){const z=Number(g.heightM[i]);if(g.valid[i]!==1||!Number.isFinite(z)||z<band.minM||z>=band.maxM)continue;const lon=Number(g.longitude[i]),lat=Number(g.latitude[i]);if(!Number.isFinite(lon)||!Number.isFinite(lat)||lon<-180||lon>180||lat<o.meta.south||lat>o.meta.north)continue;const p=pixelPoint(lon,lat,o,w,h);rc.moveTo(p.x+radius,p.y);rc.arc(p.x,p.y,radius,0,Math.PI*2);heights.push(z);cells++}rc.fill();if(cells<8)return null;const mask=document.createElement('canvas');mask.width=w;mask.height=h;const mc=mask.getContext('2d');if(!mc)throw new Error('GK2A_CTH_MASK_SMOOTH_CONTEXT');const blurPx=clamp(sourceStep*.62,1.25,14);mc.filter=`blur(${blurPx}px)`;mc.globalAlpha=.96;mc.drawImage(raw,0,0);mc.filter='none';mc.globalAlpha=.38;mc.drawImage(raw,0,0);mc.globalAlpha=1;const layer=document.createElement('canvas');layer.width=w;layer.height=h;const lc=layer.getContext('2d');if(!lc)throw new Error('GK2A_CTH_LAYER_CONTEXT');lc.drawImage(o.canvas,0,0);lc.globalCompositeOperation='destination-in';lc.drawImage(mask,0,0);lc.globalCompositeOperation='source-over';return Object.freeze({canvas:layer,cells,medianHeightM:median(heights),minM:band.minM,maxM:band.maxM,id:band.id,sourceStepPx:sourceStep,maskRadiusPx:radius,maskBlurPx:blurPx})}
export class Gk2aCthReliefRuntime{
 constructor({viewer,Cesium,baseUrl='/clouds/gk2a/cth',observedBaseUrl='/clouds'}={}){if(!viewer||viewer.isDestroyed?.())throw new Error('GK2A_CTH_VIEWER_REQUIRED');this.viewer=viewer;this.C=Cesium||globalThis.Cesium;this.baseUrl=baseUrl.replace(/\/$/,'');this.observedBaseUrl=observedBaseUrl.replace(/\/$/,'');this.primitives=[];this.manifest=null;this.visible=false;this.generation=0}
 async load({force=false}={}){const generation=++this.generation;if(this.primitives.length&&!force)return this.manifest;const mr=await fetch(`${this.baseUrl}/manifest.json?t=${Date.now()}`,{cache:'no-cache'});if(!mr.ok)throw new Error(`GK2A_CTH_MANIFEST_${mr.status}`);const m=await mr.json();if(m.ready!==true||m.synthetic===true||m.truthClass!=='OBSERVED_DERIVED_OFFICIAL_L2'||m.units!=='m'){const d={ready:m.ready,synthetic:m.synthetic,truthClass:m.truthClass,units:m.units,sourceId:m.sourceId,sourceTransport:m.sourceTransport,gridUrl:m.gridUrl};throw new Error(`GK2A_CTH_MANIFEST_TRUTH_GATE:${JSON.stringify(d)}`)}if(typeof m.gridUrl!=='string'||!m.gridUrl.trim())throw new Error('GK2A_CTH_GRID_URL_MISSING');const gr=await fetch(new URL(m.gridUrl,`${location.origin}${this.baseUrl}/`).href,{cache:'no-cache'});if(!gr.ok)throw new Error(`GK2A_CTH_GRID_${gr.status}`);const g=await gr.json(),observed=await loadObserved(this.observedBaseUrl);if(generation!==this.generation)return null;this.#validate(g,m);this.#destroy();const built=this.#buildBands(g,observed);if(!built.length)throw new Error('GK2A_CTH_BANDS_EMPTY');this.primitives=built.map(x=>x.primitive);for(const p of this.primitives)p.show=this.visible;this.manifest=Object.freeze({...m,appearanceTruthClass:'OBSERVED_2D_GMGSI_MASKED_BY_OBSERVED_CTH_BANDS',appearanceSource:'NOAA_NESDIS_GMGSI',appearanceValidAt:observed.meta.time,renderModel:'SOURCE_CTH_ALTITUDE_BANDS_SMOOTH_DISPLAY_INTERPOLATION_NO_TRIANGLE_MESH',bands:Object.freeze(built.map(x=>Object.freeze(x.summary)))});this.viewer.scene.requestRender();return this.manifest}
 #validate(g,m){const n=g.width*g.height;if(g.synthetic===true||g.truthClass!=='OBSERVED_DERIVED_OFFICIAL_L2'||g.units!=='m')throw new Error('GK2A_CTH_GRID_TRUTH_GATE');for(const k of['longitude','latitude','heightM','valid'])if(!Array.isArray(g[k])||g[k].length!==n)throw new Error(`GK2A_CTH_GRID_${k.toUpperCase()}_SHAPE`);if(g.width!==m.width||g.height!==m.height||n<4||n>100000)throw new Error('GK2A_CTH_GRID_DIMENSION_GATE')}
 #buildBands(g,o){const C=this.C,sourceStep=estimateSourceStepPx(g,o,o.canvas.width,o.canvas.height),rect=C.Rectangle.fromDegrees(-180,o.meta.south,180,o.meta.north),out=[];for(const band of BANDS){const texture=buildBandTexture(g,o,band,sourceStep);if(!texture||!Number.isFinite(texture.medianHeightM))continue;const material=C.Material.fromType('Image',{image:texture.canvas,repeat:new C.Cartesian2(1,1),color:C.Color.WHITE.withAlpha(.86),transparent:true}),geometry=new C.RectangleGeometry({rectangle:rect,height:texture.medianHeightM,granularity:C.Math.toRadians(.35),vertexFormat:C.EllipsoidSurfaceAppearance.VERTEX_FORMAT}),appearance=new C.EllipsoidSurfaceAppearance({aboveGround:true,faceForward:true,translucent:true,material}),primitive=this.viewer.scene.primitives.add(new C.Primitive({geometryInstances:new C.GeometryInstance({geometry}),appearance,allowPicking:false,asynchronous:false,show:false}));out.push({primitive,summary:{id:texture.id,minM:texture.minM,maxM:texture.maxM,medianHeightM:Math.round(texture.medianHeightM),sourceCellCount:texture.cells,sourceStepPx:Number(texture.sourceStepPx.toFixed(2)),maskRadiusPx:Number(texture.maskRadiusPx.toFixed(2)),maskBlurPx:Number(texture.maskBlurPx.toFixed(2))}})}return out}
 setVisible(show){this.visible=!!show;for(const p of this.primitives)p.show=this.visible;this.viewer.scene.requestRender()}
 async show(){this.visible=true;if(!this.primitives.length)await this.load();for(const p of this.primitives)p.show=true;this.viewer.scene.requestRender();return this.manifest}
 hide(){this.setVisible(false)}
 #destroy(){for(const p of this.primitives)try{this.viewer.scene.primitives.remove(p)}catch(_){}this.primitives=[]}
 dispose(){this.generation++;this.#destroy();this.manifest=null;this.visible=false}
}
